00038 #ifndef __UNITPARTITIONER__
00039 #define __UNITPARTITIONER__
00040 
00041 #include "Unit.h"
00042 
00043 #include "CommonDef.h"
00044 
00045 namespace vtm {
00046 
00047 static_assert(MAX_CU_TILING_PARTITIONS >= 4, "Minimum required number of partitions for the Partitioning type is 4!");
00048 typedef std::vector <UnitArea> Partitioning;
00049 
00051 // PartManager class - manages the partitioning tree
00052 //
00053 // contains the currently processed partitioning area (currArea)
00054 // as well as the all partitioning decisions that led to this area
00055 // being processed (in m_partStack).
00057 
00058 enum PartSplit
00059 {
00060   CTU_LEVEL        = 0,
00061   CU_QUAD_SPLIT,
00062 
00063   CU_HORZ_SPLIT,
00064   CU_VERT_SPLIT,
00065   CU_TRIH_SPLIT,
00066   CU_TRIV_SPLIT,
00067   TU_MAX_TR_SPLIT,
00068   TU_NO_ISP,
00069   TU_1D_HORZ_SPLIT,
00070   TU_1D_VERT_SPLIT,
00071   SBT_VER_HALF_POS0_SPLIT,
00072   SBT_VER_HALF_POS1_SPLIT,
00073   SBT_HOR_HALF_POS0_SPLIT,
00074   SBT_HOR_HALF_POS1_SPLIT,
00075   SBT_VER_QUAD_POS0_SPLIT,
00076   SBT_VER_QUAD_POS1_SPLIT,
00077   SBT_HOR_QUAD_POS0_SPLIT,
00078   SBT_HOR_QUAD_POS1_SPLIT,
00079   NUM_PART_SPLIT,
00080   CU_MT_SPLIT             = 1000, 
00081   CU_BT_SPLIT             = 1001, 
00082   CU_DONT_SPLIT           = 2000  
00083 };
00084 
00085 
00086 
00087 struct PartLevel
00088 {
00089   PartSplit    split;
00090   Partitioning parts;
00091   unsigned     idx;
00092   bool         checkdIfImplicit;
00093   bool         isImplicit;
00094   PartSplit    implicitSplit;
00095   PartSplit    firstSubPartSplit;
00096   bool         canQtSplit;
00097   bool         qgEnable;
00098   bool         qgChromaEnable;
00099   int          modeType;
00100 
00101   PartLevel();
00102   PartLevel( const PartSplit _split, const Partitioning&  _parts );
00103   PartLevel( const PartSplit _split,       Partitioning&& _parts );
00104 };
00105 
00106 // set depending on max QT / BT possibilities
00107 typedef static_vector<PartLevel, 2 * MAX_CU_DEPTH + 1> PartitioningStack;
00108 
00109 class Partitioner
00110 {
00111 protected:
00112   PartitioningStack m_partStack;
00113 #if _DEBUG
00114   UnitArea          m_currArea;
00115 #endif
00116 
00117 public:
00118   unsigned currDepth;
00119   unsigned currQtDepth;
00120   unsigned currTrDepth;
00121   unsigned currBtDepth;
00122   unsigned currMtDepth;
00123   unsigned currSubdiv;
00124   Position currQgPos;
00125   Position currQgChromaPos;
00126 
00127   unsigned currImplicitBtDepth;
00128   ChannelType chType;
00129   TreeType treeType;
00130   ModeType modeType;
00131 
00132   virtual ~Partitioner                    () { }
00133 
00134   const PartLevel& currPartLevel          () const { return m_partStack.back(); }
00135   const UnitArea&  currArea               () const { return currPartLevel().parts[currPartIdx()]; }
00136   const unsigned   currPartIdx            () const { return currPartLevel().idx; }
00137   const PartitioningStack& getPartStack   () const { return m_partStack; }
00138   const bool currQgEnable                 () const { return currPartLevel().qgEnable; }
00139   const bool currQgChromaEnable           () const { return currPartLevel().qgChromaEnable; }
00140 
00141   SplitSeries getSplitSeries              () const;
00142   ModeTypeSeries getModeTypeSeries        () const;
00143 
00144   virtual void initCtu                    ( const UnitArea& ctuArea, const ChannelType _chType, const Slice& slice )    = 0;
00145   virtual void splitCurrArea              ( const PartSplit split, const CodingStructure &cs )                          = 0;
00146   virtual void exitCurrSplit              ()                                                                            = 0;
00147   virtual bool nextPart                   ( const CodingStructure &cs, bool autoPop = false )                           = 0;
00148   virtual bool hasNextPart                ()                                                                            = 0;
00149 
00150   virtual void setCUData                  ( CodingUnit& cu );
00151 
00152   virtual void copyState                  ( const Partitioner& other );
00153 
00154 public:
00155   virtual void canSplit                   ( const CodingStructure &cs, bool& canNo, bool& canQt, bool& canBh, bool& canBv, bool& canTh, bool& canTv ) = 0;
00156   virtual bool canSplit                   ( const PartSplit split,                          const CodingStructure &cs ) = 0;
00157   virtual bool isSplitImplicit            ( const PartSplit split,                          const CodingStructure &cs ) = 0;
00158   virtual PartSplit getImplicitSplit      (                                                 const CodingStructure &cs ) = 0;
00159   bool isSepTree                          ( const CodingStructure &cs );
00160   bool isLocalSepTree                     ( const CodingStructure &cs );
00161   bool isConsInter                        () { return modeType == MODE_TYPE_INTER; }
00162   bool isConsIntra                        () { return modeType == MODE_TYPE_INTRA; }
00163 };
00164 
00165 class AdaptiveDepthPartitioner : public Partitioner
00166 {
00167 public:
00168   void setMaxMinDepth( unsigned& minDepth, unsigned& maxDepth, const CodingStructure& cs ) const;
00169 };
00170 
00171 class QTBTPartitioner : public AdaptiveDepthPartitioner
00172 {
00173 public:
00174   void initCtu                    ( const UnitArea& ctuArea, const ChannelType _chType, const Slice& slice );
00175   void splitCurrArea              ( const PartSplit split, const CodingStructure &cs );
00176   void exitCurrSplit              ();
00177   bool nextPart                   ( const CodingStructure &cs, bool autoPop = false );
00178   bool hasNextPart                ();
00179 
00180   void canSplit                   ( const CodingStructure &cs, bool& canNo, bool& canQt, bool& canBh, bool& canBv, bool& canTh, bool& canTv );
00181   bool canSplit                   ( const PartSplit split,                          const CodingStructure &cs );
00182   bool isSplitImplicit            ( const PartSplit split,                          const CodingStructure &cs );
00183   PartSplit getImplicitSplit      (                                                 const CodingStructure &cs );
00184 };
00185 
00186 class TUIntraSubPartitioner : public Partitioner
00187 {
00188 public:
00189   TUIntraSubPartitioner(Partitioner& _initialState)
00190   {
00191     //we copy the input partitioner data
00192     m_partStack.push_back(PartLevel(TU_NO_ISP, { _initialState.currArea() }));
00193 
00194     currDepth    = _initialState.currDepth;
00195     currQtDepth  = _initialState.currQtDepth;
00196     currTrDepth  = _initialState.currTrDepth;
00197     currBtDepth  = _initialState.currBtDepth;
00198     currMtDepth  = _initialState.currMtDepth;
00199     chType       = _initialState.chType;
00200 #if _DEBUG
00201     m_currArea   = _initialState.currArea();
00202 #endif
00203     treeType     = _initialState.treeType;
00204     modeType     = _initialState.modeType;
00205   }
00206 
00207   void initCtu               (const UnitArea& ctuArea, const ChannelType chType, const Slice& slice) {}; // not needed
00208   void splitCurrArea         (const PartSplit split, const CodingStructure &cs);
00209   void exitCurrSplit         ();
00210   bool nextPart              (const CodingStructure &cs, bool autoPop = false);
00211   bool hasNextPart           ();
00212   void canSplit              (const CodingStructure &cs, bool& canNo, bool& canQt, bool& canBh, bool& canBv, bool& canTh, bool& canTv) {};
00213   bool canSplit              (const PartSplit split, const CodingStructure &cs);
00214   bool isSplitImplicit       (const PartSplit split, const CodingStructure &cs) { return false; }; //not needed
00215   PartSplit getImplicitSplit (const CodingStructure &cs) { return CU_DONT_SPLIT; }; //not needed
00216 };
00217 
00219 // Partitioner namespace - contains methods calculating the actual splits
00221 
00222 namespace PartitionerImpl
00223 {
00224   Partitioning getCUSubPartitions( const UnitArea   &cuArea, const CodingStructure &cs, const PartSplit splitType = CU_QUAD_SPLIT );
00225   Partitioning getMaxTuTiling    ( const UnitArea& curArea, const CodingStructure &cs );
00226   void    getTUIntraSubPartitions( Partitioning &sub, const UnitArea &tuArea, const CodingStructure &cs, const PartSplit splitType );
00227   Partitioning getSbtTuTiling    ( const UnitArea& curArea, const CodingStructure &cs, const PartSplit splitType );
00228 };
00229 
00230 } // namespace vtm
